'use client';

import { useEffect, useState } from 'react';

import { Sheet, SheetContent, SheetTitle } from '@/registry/ndeko/ui/sheet';

import { AppSidebar } from './app-sidebar';
import {
  CURRENT_USER_ID,
  INITIAL_NOTIFICATIONS,
  INITIAL_PROFILE,
  INITIAL_WORKSPACE,
  PEOPLE,
  SETTINGS_GROUPS,
  WORKSPACE_FACTS,
  WORKSPACE_ID,
  type NavItem,
  type NotificationValues,
  type PageId,
  type Person,
  type ProfileValues,
  type Workspace,
  type WorkspaceValues,
} from './data';
import { NotificationsPage } from './notifications-page';
import { ProfilePage } from './profile-page';
import { CommandPalette } from './search-palette';
import { TopBar } from './top-bar';
import { WorkspacePage } from './workspace-page';

const NAV_ITEMS = SETTINGS_GROUPS.flatMap((group) => group.items);

const SETTINGS_ANCESTOR = 'Settings';

function navItemOf(pageId: PageId): NavItem {
  const item = NAV_ITEMS.find((candidate) => candidate.id === pageId);
  if (item) {
    return item;
  }
  return NAV_ITEMS[0];
}

function personOf(personId: string) {
  const person = PEOPLE.find((candidate) => candidate.id === personId);
  if (person) {
    return person;
  }
  return PEOPLE[0];
}

function accountOf(profile: ProfileValues): Person {
  const person = personOf(CURRENT_USER_ID);
  return {
    ...person,
    name: profile.name,
    role: profile.title,
    avatar: profile.photo,
  };
}

function workspaceOf(values: WorkspaceValues): Workspace {
  return {
    id: WORKSPACE_ID,
    name: values.name,
    memberCount: WORKSPACE_FACTS.members,
  };
}

function isPaletteShortcut(event: KeyboardEvent) {
  const isKKey = event.key.toLowerCase() === 'k';
  const hasModifier = event.metaKey || event.ctrlKey;
  return isKKey && hasModifier;
}

export default function Application03() {
  const [activePageId, setActivePageId] = useState<PageId>('profile');
  const [isNavigationOpen, setIsNavigationOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);
  const [profile, setProfile] = useState<ProfileValues>(INITIAL_PROFILE);
  const [notifications, setNotifications] = useState<NotificationValues>(
    INITIAL_NOTIFICATIONS
  );
  const [workspaceValues, setWorkspaceValues] =
    useState<WorkspaceValues>(INITIAL_WORKSPACE);

  const activePage = navItemOf(activePageId);
  const account = accountOf(profile);
  const workspace = workspaceOf(workspaceValues);

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (isPaletteShortcut(event)) {
        event.preventDefault();
        setIsPaletteOpen((isOpen) => !isOpen);
      }
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  function navigate(pageId: PageId) {
    setActivePageId(pageId);
    setIsNavigationOpen(false);
  }

  function openSearch() {
    setIsNavigationOpen(false);
    setIsPaletteOpen(true);
  }

  function openNavigation() {
    setIsNavigationOpen(true);
  }

  const sidebarProps = {
    workspace,
    groups: SETTINGS_GROUPS,
    activePageId,
    person: account,
    onNavigate: navigate,
    onOpenSearch: openSearch,
  };

  return (
    <div className='bg-sidebar text-foreground flex h-dvh min-h-0 w-full md:p-2'>
      <aside
        aria-label='Sidebar'
        className='hidden w-60 shrink-0 pr-2 md:block'
      >
        <AppSidebar {...sidebarProps} />
      </aside>
      <Sheet open={isNavigationOpen} onOpenChange={setIsNavigationOpen}>
        <SheetContent
          side='left'
          showCloseButton={false}
          className='bg-sidebar w-72 gap-0 p-2'
        >
          <SheetTitle className='sr-only'>Navigation</SheetTitle>
          <AppSidebar {...sidebarProps} />
        </SheetContent>
      </Sheet>
      <main className='bg-background md:hairline-ring md:ring-border flex min-w-0 flex-1 flex-col overflow-clip md:rounded-xl md:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <TopBar
          page={activePage}
          ancestor={SETTINGS_ANCESTOR}
          people={PEOPLE}
          onOpenNavigation={openNavigation}
        />
        {activePageId === 'profile' && (
          <ProfilePage
            values={profile}
            workspaceName={workspace.name}
            onSaved={setProfile}
          />
        )}
        {activePageId === 'notifications' && (
          <NotificationsPage
            values={notifications}
            onSaved={setNotifications}
          />
        )}
        {activePageId === 'workspace' && (
          <WorkspacePage
            values={workspaceValues}
            onSaved={setWorkspaceValues}
          />
        )}
      </main>
      <CommandPalette
        open={isPaletteOpen}
        onOpenChange={setIsPaletteOpen}
        groups={SETTINGS_GROUPS}
        onNavigate={navigate}
      />
    </div>
  );
}

'use client';

import { useId } from 'react';

import { ArrowLeftIcon } from '@/registry/ndeko/lib/icons';

import { AccountMenu } from './account-menu';
import type { NavGroup, NavItem, PageId, Person, Workspace } from './data';
import { SearchTrigger } from './search-palette';
import { NAV_ROW, NavRow } from './sidebar-parts';
import { WorkspaceSwitcher } from './workspace-switcher';

type AppSidebarProps = {
  workspace: Workspace;
  groups: NavGroup[];
  activePageId: PageId;
  person: Person;
  onNavigate: (pageId: PageId) => void;
  onOpenSearch: () => void;
};

function GroupLabel({ group }: { group: NavGroup }) {
  if (!group.label) {
    return null;
  }
  return (
    <p className='text-muted-foreground flex h-6 items-center px-2 text-xs font-medium'>
      {group.label}
    </p>
  );
}

function keepWorkspace() {
  return undefined;
}

/** The settings rail. Back to app is a plain link, so the template can point it at the app it lives in. */
export function AppSidebar({
  workspace,
  groups,
  activePageId,
  person,
  onNavigate,
  onOpenSearch,
}: AppSidebarProps) {
  const indicatorId = useId();

  function selectItem(item: NavItem) {
    onNavigate(item.id);
  }

  function openWorkspaceSettings() {
    onNavigate('workspace');
  }

  return (
    <div className='flex h-full min-h-0 flex-col gap-3'>
      <div className='flex flex-col gap-2'>
        <WorkspaceSwitcher
          workspaces={[workspace]}
          current={workspace}
          onSelect={keepWorkspace}
          onOpenSettings={openWorkspaceSettings}
        />
        <div className='flex items-center'>
          <SearchTrigger onOpen={onOpenSearch} />
        </div>
      </div>
      <nav
        aria-label='Settings'
        className='-mx-2 flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-2'
      >
        <a href='#' className={NAV_ROW}>
          <ArrowLeftIcon />
          <span className='relative min-w-0 flex-1 truncate'>Back to app</span>
        </a>
        {groups.map((group) => (
          <div key={group.id} className='flex flex-col gap-0.5'>
            <GroupLabel group={group} />
            <ul className='flex flex-col gap-px'>
              {group.items.map((item) => (
                <NavRow
                  key={item.id}
                  item={item}
                  isActive={item.id === activePageId}
                  indicatorId={indicatorId}
                  onSelect={selectItem}
                />
              ))}
            </ul>
          </div>
        ))}
      </nav>
      <AccountMenu person={person} onOpenSettings={onNavigate} />
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { Avatar, AvatarImage } from '@/registry/ndeko/ui/avatar';

import type { NavItem, Person } from './data';

export const NAV_ROW = [
  'relative flex h-7 w-full min-w-0 items-center gap-2 rounded-md px-2 text-left text-[13px] font-medium text-foreground outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
  "[&_svg]:pointer-events-none [&_svg]:relative [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
].join(' ');

const INDICATOR_TRAVEL: Transition = {
  duration: 0.25,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return INDICATOR_TRAVEL;
}

/** The one highlight of the active row. It travels from the old row to the new one. */
export function ActiveRowIndicator({ layoutId }: { layoutId: string }) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.span
      aria-hidden='true'
      layoutId={layoutId}
      transition={travelOf(shouldReduceMotion)}
      className='bg-foreground/[0.07] absolute inset-0 rounded-md'
    />
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={className} seed={person.id}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
    </Avatar>
  );
}

export function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

type NavRowProps = {
  item: NavItem;
  isActive: boolean;
  indicatorId: string;
  onSelect: (item: NavItem) => void;
};

export function NavRow({ item, isActive, indicatorId, onSelect }: NavRowProps) {
  const ItemIcon = item.icon;
  const ariaCurrent = ariaCurrentOf(isActive);

  function selectItem() {
    onSelect(item);
  }

  return (
    <li>
      <button
        type='button'
        aria-current={ariaCurrent}
        onClick={selectItem}
        className={NAV_ROW}
      >
        {isActive && <ActiveRowIndicator layoutId={indicatorId} />}
        <ItemIcon />
        <span className='relative min-w-0 flex-1 truncate'>{item.label}</span>
      </button>
    </li>
  );
}

'use client';

import {
  ChevronsUpDownIcon,
  PlusIcon,
  SettingsIcon,
} from '@/registry/ndeko/lib/icons';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Workspace } from './data';

const TRIGGER = [
  'flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md px-1.5 text-left outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 data-popup-open:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
].join(' ');

function memberCountLabelOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}

type WorkspaceSwitcherProps = {
  workspaces: Workspace[];
  current: Workspace;
  onSelect: (workspaceId: string) => void;
  onOpenSettings: () => void;
};

export function WorkspaceSwitcher({
  workspaces,
  current,
  onSelect,
  onOpenSettings,
}: WorkspaceSwitcherProps) {
  function selectWorkspace(value: unknown) {
    if (typeof value === 'string') {
      onSelect(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Workspace: ${current.name}`}
            className={TRIGGER}
          />
        }
      >
        <CompanyMark seed={current.id} className='size-6 rounded-md' />
        <span className='min-w-0 flex-1 truncate text-[13px] font-semibold'>
          {current.name}
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-64'>
        <DropdownMenuLabel>Workspaces</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          value={current.id}
          onValueChange={selectWorkspace}
        >
          {workspaces.map((workspace) => (
            <DropdownMenuRadioItem
              key={workspace.id}
              value={workspace.id}
              closeOnClick
              className='h-9'
            >
              <CompanyMark seed={workspace.id} />
              <span className='min-w-0 flex-1 truncate'>{workspace.name}</span>
              <Kbd aria-hidden='true'>{workspace.memberCount}</Kbd>
              <span className='sr-only'>
                {memberCountLabelOf(workspace.memberCount)}
              </span>
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem onClick={onOpenSettings}>
          <SettingsIcon />
          Settings
        </DropdownMenuItem>
        <DropdownMenuItem>
          <PlusIcon />
          Add workspace
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { SearchIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/registry/ndeko/ui/command';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { NavGroup, PageId } from './data';

function headingOf(group: NavGroup) {
  if (group.team) {
    return group.team.name;
  }
  if (group.label) {
    return group.label;
  }
  return 'Personal';
}

export function SearchTrigger({ onOpen }: { onOpen: () => void }) {
  return (
    <button
      type='button'
      onClick={onOpen}
      className={cn(
        CONTROL_RECIPE,
        'text-muted-foreground flex h-8 min-w-0 flex-1 cursor-pointer items-center gap-2 px-2.5 text-left'
      )}
    >
      <SearchIcon className='size-4 shrink-0' />
      <span className='min-w-0 flex-1 truncate'>Search</span>
      <Kbd>⌘K</Kbd>
    </button>
  );
}

type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  groups: NavGroup[];
  onNavigate: (pageId: PageId) => void;
};

export function CommandPalette({
  open,
  onOpenChange,
  groups,
  onNavigate,
}: CommandPaletteProps) {
  function closePalette() {
    onOpenChange(false);
  }

  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      title='Search'
      description='Go to a settings page'
    >
      <CommandInput placeholder='Go to a settings page' />
      <CommandList>
        <CommandEmpty>
          Nothing matches. Try the name of a settings page.
        </CommandEmpty>
        {groups.map((group) => (
          <CommandGroup key={group.id} heading={headingOf(group)}>
            {group.items.map((item) => {
              const ItemIcon = item.icon;

              function goToPage() {
                closePalette();
                onNavigate(item.id);
              }

              return (
                <CommandItem
                  key={item.id}
                  value={`${group.id} ${item.label}`}
                  onSelect={goToPage}
                >
                  <ItemIcon />
                  {item.label}
                </CommandItem>
              );
            })}
          </CommandGroup>
        ))}
      </CommandList>
    </CommandDialog>
  );
}

'use client';

import {
  BellIcon,
  ChevronsUpDownIcon,
  CommandIcon,
  LifeBuoyIcon,
  LogOutIcon,
  UserIcon,
} from '@/registry/ndeko/lib/icons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { PageId, Person } from './data';
import { PersonAvatar } from './sidebar-parts';

const TRIGGER = [
  'flex h-9 w-full min-w-0 items-center gap-2 rounded-md px-1.5 text-left outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 data-popup-open:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
].join(' ');

type AccountMenuProps = {
  person: Person;
  onOpenSettings: (pageId: PageId) => void;
};

export function AccountMenuItems({ person, onOpenSettings }: AccountMenuProps) {
  function openProfile() {
    onOpenSettings('profile');
  }

  function openNotifications() {
    onOpenSettings('notifications');
  }

  return (
    <>
      <div className='flex items-center gap-2.5 px-2 py-2'>
        <PersonAvatar person={person} />
        <div className='min-w-0'>
          <p className='truncate text-[13px] font-medium'>{person.name}</p>
          <p className='text-muted-foreground truncate text-xs'>
            {person.role}
          </p>
        </div>
      </div>
      <DropdownMenuSeparator />
      <DropdownMenuItem onClick={openProfile}>
        <UserIcon />
        Profile
      </DropdownMenuItem>
      <DropdownMenuItem onClick={openNotifications}>
        <BellIcon />
        Notifications
      </DropdownMenuItem>
      <DropdownMenuItem>
        <CommandIcon />
        Keyboard shortcuts
        <Kbd className='ml-auto'>?</Kbd>
      </DropdownMenuItem>
      <DropdownMenuItem>
        <LifeBuoyIcon />
        Help and docs
      </DropdownMenuItem>
      <DropdownMenuSeparator />
      <DropdownMenuItem variant='destructive'>
        <LogOutIcon />
        Log out
      </DropdownMenuItem>
    </>
  );
}

export function AccountMenu({ person, onOpenSettings }: AccountMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Account: ${person.name}`}
            className={TRIGGER}
          />
        }
      >
        <PersonAvatar person={person} className='size-6 text-[10px]' />
        <span className='min-w-0 flex-1 truncate text-[13px] font-medium'>
          {person.name}
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent side='top' align='start' className='w-60'>
        <AccountMenuItems person={person} onOpenSettings={onOpenSettings} />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { MenuIcon } from '@/registry/ndeko/lib/icons';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/registry/ndeko/ui/breadcrumb';
import { Button } from '@/registry/ndeko/ui/button';

import type { NavItem, Person } from './data';
import { PersonAvatar } from './sidebar-parts';

const STACK_LIMIT = 4;

function AvatarStack({ people }: { people: Person[] }) {
  const shown = people.slice(0, STACK_LIMIT);
  const hiddenCount = people.length - shown.length;
  const hasHidden = hiddenCount > 0;

  return (
    <div
      role='group'
      aria-label='Team members'
      className='hidden items-center sm:flex'
    >
      {shown.map((person) => (
        <PersonAvatar
          key={person.id}
          person={person}
          className='ring-background -ml-1.5 size-6 text-[10px] ring-2 first:ml-0'
        />
      ))}
      {hasHidden && (
        <span className='bg-muted text-muted-foreground ring-background -ml-1.5 inline-flex size-6 items-center justify-center rounded-full text-[10px] font-medium tabular-nums ring-2'>
          +{hiddenCount}
        </span>
      )}
    </div>
  );
}

type TopBarProps = {
  page: NavItem;
  ancestor?: string;
  people: Person[];
  onOpenNavigation: () => void;
};

export function TopBar({
  page,
  ancestor,
  people,
  onOpenNavigation,
}: TopBarProps) {
  const PageIcon = page.icon;
  const hasAncestor = Boolean(ancestor);

  return (
    <header className='hairline-b border-border flex h-11 shrink-0 items-center gap-2 px-3 md:px-4'>
      <Button
        variant='ghost'
        size='icon-sm'
        aria-label='Open navigation'
        onClick={onOpenNavigation}
        className='text-muted-foreground md:hidden'
      >
        <MenuIcon />
      </Button>
      <Breadcrumb className='min-w-0'>
        <BreadcrumbList className='flex-nowrap'>
          <li aria-hidden='true' className='flex'>
            <PageIcon className='text-muted-foreground size-4 shrink-0' />
          </li>
          {hasAncestor && (
            <>
              <BreadcrumbItem className='hidden sm:inline-flex'>
                {ancestor}
              </BreadcrumbItem>
              <BreadcrumbSeparator className='hidden sm:block' />
            </>
          )}
          <BreadcrumbItem className='min-w-0'>
            <BreadcrumbPage className='truncate'>{page.label}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>
      <div className='ml-auto flex items-center gap-2'>
        <AvatarStack people={people} />
      </div>
    </header>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { GlobeIcon, MailIcon, UserIcon } from '@/registry/ndeko/lib/icons';

import {
  BIO_MAX_LENGTH,
  INITIAL_PROFILE,
  LANGUAGES,
  PROFILE_HOST,
  PROFILE_SECTION_KEYS,
  type ProfileField,
  type ProfileSectionId,
  type ProfileValues,
  TIME_FORMAT_SAMPLE,
  TIME_FORMATS,
  TIME_ZONES,
  WEEK_STARTS,
} from './data';
import { BioRow, PhotoRow } from './profile-fields';
import {
  ChoiceRow,
  SectionPanel,
  SectionTabs,
  SelectRow,
  SettingsPage,
  SettingsSection,
  SwitchRow,
  TextRow,
  UnsavedBar,
  hasChangeIn,
  useSettingsDraft,
  type NavItem,
} from './settings-kit';
import {
  FIELD_SECTION,
  errorCountOf,
  errorsOf,
  firstErrorFieldOf,
  withoutError,
  type ProfileErrors,
} from './validation';

const SECTIONS = [
  { id: 'profile', label: 'Profile', icon: UserIcon },
  { id: 'contact', label: 'Contact', icon: MailIcon },
  { id: 'region', label: 'Language and region', icon: GlobeIcon },
] as const;

const SAMPLE_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SAMPLE_VARIANTS: Variants = {
  enter: { opacity: 0, y: 4 },
  visible: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -4 },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function sampleVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SAMPLE_VARIANTS;
}

function fieldIdOf(field: ProfileField) {
  return `profile-${field}`;
}

function fixMessageOf(count: number) {
  if (count === 0) {
    return undefined;
  }
  if (count === 1) {
    return 'Fix 1 field to save';
  }
  return `Fix ${count} fields to save`;
}

function pageAddressOf(username: string) {
  const handle = username.trim();
  if (handle.length === 0) {
    return `${PROFILE_HOST}your-name`;
  }
  return `${PROFILE_HOST}${handle}`;
}

function emailLineOf(isChanged: boolean) {
  if (isChanged) {
    return 'A confirmation link goes to the new address before it replaces the old one';
  }
  return 'Verified, used to sign in and for notifications';
}

function focusField(field: ProfileField) {
  const fieldId = fieldIdOf(field);
  window.requestAnimationFrame(() => {
    document.getElementById(fieldId)?.focus();
  });
}

/** The sample line under the time format swaps with the format it describes. */
function TimeSample({ format }: { format: ProfileValues['timeFormat'] }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = sampleVariantsOf(shouldReduceMotion);

  return (
    <span className='relative block'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={format}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SAMPLE_TRANSITION}
          className='block'
        >
          {TIME_FORMAT_SAMPLE[format]}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

type ProfilePageProps = {
  values: ProfileValues;
  workspaceName: string;
  onSaved: (values: ProfileValues) => void;
};

export function ProfilePage({
  values,
  workspaceName,
  onSaved,
}: ProfilePageProps) {
  const settings = useSettingsDraft<ProfileValues>(values, onSaved);
  const [section, setSection] = useState<ProfileSectionId>('profile');
  const [hasSwitched, setHasSwitched] = useState(false);
  const [shownErrors, setShownErrors] = useState<ProfileErrors>({});
  const [photoError, setPhotoError] = useState<string | null>(null);
  const draft = settings.draft;
  const errorCount = errorCountOf(shownErrors);
  const fixMessage = fixMessageOf(errorCount);
  const pageAddress = pageAddressOf(draft.username);
  const isEmailChanged = settings.changedKeys.includes('email');
  const emailLine = emailLineOf(isEmailChanged);
  const navItems: NavItem<ProfileSectionId>[] = SECTIONS.map((item) => ({
    id: item.id,
    label: item.label,
    icon: item.icon,
    hasChanges: hasChangeIn(
      settings.changedKeys,
      PROFILE_SECTION_KEYS[item.id]
    ),
  }));

  function openSection(nextSection: ProfileSectionId) {
    setSection(nextSection);
    setHasSwitched(true);
  }

  function changeField<Field extends ProfileField>(
    field: Field,
    value: ProfileValues[Field]
  ) {
    settings.change(field, value);
    setShownErrors((previous) => withoutError(previous, field));
  }

  function save() {
    const errors = errorsOf(draft);
    const firstField = firstErrorFieldOf(errors);
    setShownErrors(errors);
    if (!firstField) {
      settings.save();
      return;
    }
    const fieldSection = FIELD_SECTION[firstField];
    if (fieldSection !== section) {
      openSection(fieldSection);
    }
    focusField(firstField);
  }

  function discard() {
    settings.discard();
    setShownErrors({});
    setPhotoError(null);
  }

  function changePhoto(photo: string) {
    changeField('photo', photo);
  }

  function changeName(name: string) {
    changeField('name', name);
  }

  function changeUsername(username: string) {
    const lowered = username.toLowerCase();
    changeField('username', lowered);
  }

  function changeTitle(title: string) {
    changeField('title', title);
  }

  function changeBio(bio: string) {
    changeField('bio', bio);
  }

  function changeEmail(email: string) {
    changeField('email', email);
  }

  function changePhone(phone: string) {
    changeField('phone', phone);
  }

  function changeShowEmail(showEmail: boolean) {
    changeField('showEmail', showEmail);
  }

  function changeLanguage(language: string) {
    changeField('language', language);
  }

  function changeTimeZone(timeZone: string) {
    changeField('timeZone', timeZone);
  }

  function changeWeekStart(weekStart: ProfileValues['weekStart']) {
    changeField('weekStart', weekStart);
  }

  function changeTimeFormat(timeFormat: ProfileValues['timeFormat']) {
    changeField('timeFormat', timeFormat);
  }

  const bar = (
    <UnsavedBar
      isShown={settings.isBarShown}
      status={settings.status}
      changeCount={settings.changedKeys.length}
      message={fixMessage}
      onDiscard={discard}
      onSave={save}
    />
  );

  return (
    <SettingsPage
      title='Profile'
      line={`How you appear to the people of ${workspaceName}, and how dates and times read for you.`}
      bar={bar}
    >
      <SectionTabs
        label='Profile sections'
        items={navItems}
        value={section}
        onValueChange={openSection}
      >
        <SectionPanel value='profile' animatesIn={hasSwitched}>
          <SettingsSection
            title='Public profile'
            line='Teammates see this next to your tasks, comments and time'
          >
            <PhotoRow
              photo={draft.photo}
              seed={INITIAL_PROFILE.username}
              error={photoError}
              onPhotoChange={changePhoto}
              onError={setPhotoError}
            />
            <TextRow
              inputId={fieldIdOf('name')}
              label='Full name'
              line='As it appears on invoices and reports'
              value={draft.name}
              error={shownErrors.name}
              autoComplete='name'
              maxLength={60}
              onValueChange={changeName}
            />
            <TextRow
              inputId={fieldIdOf('username')}
              label='Username'
              line={pageAddress}
              value={draft.username}
              error={shownErrors.username}
              autoComplete='username'
              maxLength={24}
              onValueChange={changeUsername}
            />
            <TextRow
              inputId={fieldIdOf('title')}
              label='Title'
              line='Shown under your name in the member list'
              value={draft.title}
              autoComplete='organization-title'
              maxLength={60}
              onValueChange={changeTitle}
            />
            <BioRow
              value={draft.bio}
              maxLength={BIO_MAX_LENGTH}
              onValueChange={changeBio}
            />
          </SettingsSection>
        </SectionPanel>
        <SectionPanel value='contact' animatesIn={hasSwitched}>
          <SettingsSection
            title='How teammates reach you'
            line='Your email signs you in; your phone stays optional'
          >
            <TextRow
              inputId={fieldIdOf('email')}
              type='email'
              label='Email'
              line={emailLine}
              value={draft.email}
              error={shownErrors.email}
              autoComplete='email'
              onValueChange={changeEmail}
            />
            <TextRow
              inputId={fieldIdOf('phone')}
              type='tel'
              inputMode='tel'
              label='Phone'
              line='Optional, for urgent calls from your team'
              placeholder='+234 803 555 0142'
              value={draft.phone}
              error={shownErrors.phone}
              autoComplete='tel'
              onValueChange={changePhone}
            />
            <SwitchRow
              label='Show my email to teammates'
              line='Off keeps it visible to workspace admins only'
              checked={draft.showEmail}
              onCheckedChange={changeShowEmail}
            />
          </SettingsSection>
        </SectionPanel>
        <SectionPanel value='region' animatesIn={hasSwitched}>
          <SettingsSection
            title='Language and region'
            line='Applies to the app, your emails and your exports'
          >
            <SelectRow
              label='Language'
              line='Menus, emails and dates'
              value={draft.language}
              options={LANGUAGES}
              onValueChange={changeLanguage}
            />
            <SelectRow
              label='Time zone'
              line='Due dates and reminders follow it'
              value={draft.timeZone}
              options={TIME_ZONES}
              onValueChange={changeTimeZone}
            />
            <ChoiceRow
              label='Week starts on'
              line='Calendars and weekly reports'
              value={draft.weekStart}
              options={WEEK_STARTS}
              onValueChange={changeWeekStart}
            />
            <ChoiceRow
              label='Time format'
              line={<TimeSample format={draft.timeFormat} />}
