type SelectOption = { value: string; label: string };

type SelectRowProps = {
  label: string;
  line: React.ReactNode;
  value: string;
  options: SelectOption[];
  disabled?: boolean;
  onValueChange: (value: string) => void;
};

export function SelectRow({
  label,
  line,
  value,
  options,
  disabled,
  onValueChange,
}: SelectRowProps) {
  const labelId = useId();

  function changeValue(nextValue: unknown) {
    const option = options.find((candidate) => candidate.value === nextValue);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <SettingsRow label={label} line={line} labelId={labelId}>
      <Select
        items={options}
        value={value}
        disabled={disabled}
        onValueChange={changeValue}
      >
        <SelectTrigger aria-labelledby={labelId} className='w-full sm:w-64'>
          <SelectValue />
        </SelectTrigger>
        <SelectContent align='end'>
          {options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </SettingsRow>
  );
}

type ChoiceRowProps<Value extends string> = {
  label: string;
  line: React.ReactNode;
  value: Value;
  options: ChoiceOption<Value>[];
  disabled?: boolean;
  onValueChange: (value: Value) => void;
};

export function ChoiceRow<Value extends string>({
  label,
  line,
  value,
  options,
  disabled,
  onValueChange,
}: ChoiceRowProps<Value>) {
  const labelId = useId();
  const lineId = useId();

  return (
    <SettingsRow label={label} line={line} labelId={labelId} lineId={lineId}>
      <SegmentedChoice
        options={options}
        value={value}
        labelledBy={labelId}
        describedBy={lineId}
        disabled={disabled}
        onValueChange={onValueChange}
      />
    </SettingsRow>
  );
}

